// Evidence log. docs/evidence/<network>.json is the record; docs/<NETWORK>_EVIDENCE.md is rendered
// from it after every write. Both are produced only by scripts/deploy.mjs and scripts/demo.mjs.

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { REPO_ROOT } from './deps.mjs';

const HEADER_NOTE =
  'Generated by scripts/deploy.mjs and scripts/demo.mjs. Do not edit by hand: every row comes from a transaction the scripts sent and then read back from RPC.';

function writeAtomic(path, text) {
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}`;
  writeFileSync(tmp, text);
  renameSync(tmp, path);
}

export class Evidence {
  /**
   * @param {object} o
   * @param {string} o.network
   * @param {string} o.jsonPath
   * @param {string} o.markdownPath
   */
  constructor({ network, jsonPath, markdownPath }) {
    this.network = network;
    this.jsonPath = jsonPath;
    this.markdownPath = markdownPath;
    this.data = existsSync(jsonPath)
      ? JSON.parse(readFileSync(jsonPath, 'utf8'))
      : { network, note: HEADER_NOTE, deployment: {}, companies: [], transactions: [], quotes: [], bitcoin: [], tee_calls: [] };
    for (const key of ['transactions', 'quotes', 'bitcoin', 'tee_calls', 'companies']) this.data[key] ??= [];
    this.data.deployment ??= {};
  }

  static forNetwork(network, dir) {
    const upper = network.toUpperCase();
    return new Evidence({
      network,
      jsonPath: join(dir, 'evidence', `${network}.json`),
      markdownPath: join(dir, `${upper}_EVIDENCE.md`),
    });
  }

  addTransaction(entry) {
    this.data.transactions.push({ seq: this.data.transactions.length + 1, at: new Date().toISOString(), ...entry });
    this.save();
  }

  addQuote(entry) {
    this.data.quotes.push({ at: new Date().toISOString(), ...entry });
    this.save();
  }

  addBitcoin(entry) {
    this.data.bitcoin.push({ at: new Date().toISOString(), ...entry });
    this.save();
  }

  addTeeCall(entry) {
    this.data.tee_calls.push({ at: new Date().toISOString(), ...entry });
    this.save();
  }

  setDeployment(patch) {
    this.data.deployment = { ...this.data.deployment, ...patch, updated_at: new Date().toISOString() };
    this.save();
  }

  upsertCompany(company) {
    const index = this.data.companies.findIndex((c) => c.token_id === company.token_id);
    if (index >= 0) this.data.companies[index] = { ...this.data.companies[index], ...company };
    else this.data.companies.push(company);
    this.data.companies.sort((a, b) => Number(a.token_id) - Number(b.token_id));
    this.save();
  }

  save() {
    writeAtomic(this.jsonPath, `${JSON.stringify(this.data, null, 2)}\n`);
    writeAtomic(this.markdownPath, renderMarkdown(this.data, this.jsonPath, this.markdownPath));
  }
}

const cell = (value) => String(value ?? '').replaceAll('|', '\\|').replaceAll('\n', ' ');
const code = (value) => (value ? `\`${cell(value)}\`` : '');
const link = (text, url) => (url ? `[${cell(text)}](${url})` : code(text));
const shortHash = (hash) => (hash && hash.length > 16 ? `${hash.slice(0, 8)}…${hash.slice(-6)}` : hash);

function nearAmount(yocto) {
  if (yocto === null || yocto === undefined) return '';
  const value = BigInt(yocto);
  if (value === 0n) return '0';
  if (value < 10n ** 18n) return `${value} yocto`;
  const whole = value / 10n ** 24n;
  const frac = (value % 10n ** 24n).toString().padStart(24, '0').slice(0, 5).replace(/0+$/, '');
  return `${whole}${frac ? `.${frac}` : ''} NEAR`;
}

function btcAddressUrl(network, address) {
  if (!address) return null;
  return network === 'mainnet' ? `https://mempool.space/address/${address}` : `https://mempool.space/testnet4/address/${address}`;
}

function renderMarkdown(data, jsonPath, markdownPath) {
  const network = data.network;
  const d = data.deployment;
  const lines = [];
  const jsonRel = relative(dirname(markdownPath), jsonPath) || jsonPath;
  lines.push(`# Incorpr ${network} evidence`, '', `${HEADER_NOTE} Source: \`${jsonRel}\`.`, '');
  if (d.updated_at) lines.push(`Last updated ${d.updated_at}.`, '');

  lines.push('## Deployment', '', '| Role | Account |', '|---|---|');
  const accountUrl = (id) => (d.explorer_url && id ? `${d.explorer_url}/address/${id}` : null);
  for (const [role, id] of [
    ['Registry (incorpr-registry)', d.registry],
    ['Operator (TEE agent relay)', d.operator],
    ['Compute payee', d.compute_payee],
    ['Deployer / founder', d.deployer],
    ['USDC token', d.usdc_token],
    ['MPC signer', d.mpc_contract],
    ['Intents verifier', d.intents_contract],
  ]) {
    if (id) lines.push(`| ${role} | ${link(id, accountUrl(id))} |`);
  }
  lines.push('');
  if (d.registry_code_hash || d.protocol_version) {
    lines.push('| Fact | Value |', '|---|---|');
    if (d.protocol_version !== undefined) lines.push(`| Protocol version at deploy | ${code(d.protocol_version)} |`);
    if (d.registry_code_hash) lines.push(`| Registry code hash (base58 sha256 of incorpr_registry.wasm) | ${code(d.registry_code_hash)} |`);
    if (d.registry_wasm_bytes) lines.push(`| Registry wasm bytes | ${code(d.registry_wasm_bytes)} |`);
    if (d.vault_wasm_sha256) lines.push(`| Embedded vault wasm sha256 | ${code(d.vault_wasm_sha256)} |`);
    if (d.incorporation_cost_yocto) lines.push(`| incorporation_cost() | ${nearAmount(d.incorporation_cost_yocto)} |`);
    lines.push('');
  }

  if (d.tee) {
    lines.push('## TEE policy pinned at deploy', '');
    lines.push(`Signers come from a NEAR AI Cloud attestation report fetched with a fresh nonce at deploy time.`, '');
    lines.push('| Field | Value |', '|---|---|');
    lines.push(`| Model | ${code(d.tee.model)} |`);
    lines.push(`| tee_prompt_hash (sha256 of TREASURY_SYSTEM_PROMPT) | ${code(d.tee.prompt_hash)} |`);
    lines.push(`| Attestation nonce | ${code(d.tee.nonce)} |`);
    for (const node of d.tee.nodes ?? []) {
      const checks = Object.entries(node.checks ?? {})
        .map(([k, v]) => `${k}=${v === true ? 'pass' : v === false ? 'FAIL' : v}`)
        .join(', ');
      lines.push(`| Signer ${code(node.signing_address)} | ${cell(checks)} |`);
    }
    lines.push('');
  }

  if (data.companies.length) {
    lines.push('## Companies', '', '| Token | Name | Vault | Price per call | BTC | EVM | SOL |', '|---|---|---|---|---|---|---|');
    for (const c of data.companies) {
      lines.push(
        `| ${cell(c.token_id)} | ${cell(c.name)} | ${link(c.vault, accountUrl(c.vault))} | ${c.price_micro_usdc ? `${Number(c.price_micro_usdc) / 1e6} USDC` : ''} | ${link(c.btc, btcAddressUrl(network, c.btc))} | ${code(c.evm)} | ${code(c.sol)} |`,
      );
    }
    lines.push('');
  }

  const txs = data.transactions;
  if (txs.length) {
    lines.push('## Transactions', '', '| # | Step | Purpose | Method | Signer → receiver | Deposit | Result | Tx |', '|---|---|---|---|---|---|---|---|');
    for (const t of txs) {
      const result =
        t.status === 'success' ? 'success' : t.expected_failure ? `rejected as expected: ${code(t.error)}` : `**failed**: ${code(t.error)}`;
      lines.push(
        `| ${t.seq} | ${cell(t.step)} | ${cell(t.purpose)} | ${code(t.method)} | ${code(t.signer)} → ${code(t.receiver)} | ${nearAmount(t.deposit_yocto)} | ${result} | ${link(shortHash(t.tx_hash), t.explorer_url)} |`,
      );
    }
    lines.push('');
    const rejected = txs.filter((t) => t.expected_failure && t.status === 'failure');
    if (rejected.length) {
      lines.push('## Rejected on purpose', '', 'Each row is a real transaction that the contracts refused. The error code is read from the transaction outcome.', '');
      lines.push('| # | Attempt | Error | Tx |', '|---|---|---|---|');
      for (const t of rejected) lines.push(`| ${t.seq} | ${cell(t.purpose)} | ${code(t.error)} | ${link(t.tx_hash, t.explorer_url)} |`);
      lines.push('');
    }
  }

  if (data.tee_calls.length) {
    lines.push('## TEE service calls', '', '| Token | call_id | Model | Chat id | Signing address | Checks |', '|---|---|---|---|---|---|');
    for (const t of data.tee_calls) {
      const checks = Object.entries(t.checks ?? {})
        .map(([k, v]) => `${k}=${v === true ? 'pass' : v === false ? 'FAIL' : v}`)
        .join(', ');
      lines.push(`| ${cell(t.token_id)} | ${code(shortHash(t.call_id))} | ${code(t.model)} | ${code(t.chat_id)} | ${code(t.signing_address)} | ${cell(checks)} |`);
    }
    lines.push('');
  }

  if (data.quotes.length) {
    lines.push('## 1Click quotes (dry: true, nothing executed)', '', '| Pair | Amount in | Amount out | Min out | Vault floor | Note |', '|---|---|---|---|---|---|');
    for (const q of data.quotes) {
      lines.push(
        `| ${code(q.origin_asset)} → ${code(q.destination_asset)} | ${cell(q.amount_in)} | ${cell(q.amount_out ?? '')} | ${cell(q.min_amount_out ?? '')} | ${cell(q.floor_min_buy ?? '')} | ${cell([q.error, q.note].filter(Boolean).join('; '))} |`,
      );
    }
    lines.push('');
  }

  if (data.bitcoin.length) {
    lines.push('## Bitcoin transactions signed by the vault through the MPC signer', '', '| From | To | Amount (sats) | Fee (sats) | Txid | NEAR signature txs |', '|---|---|---|---|---|---|');
    for (const b of data.bitcoin) {
      const sigs = (b.near_signature_txs ?? []).map((h) => code(shortHash(h))).join(', ');
      lines.push(`| ${code(b.from)} | ${code(b.to)} | ${cell(b.amount_sats)} | ${cell(b.fee_sats)} | ${link(b.txid, b.explorer_url)} | ${sigs} |`);
    }
    lines.push('');
  }

  return `${lines.join('\n')}\n`;
}

export const DOCS_DIR = join(REPO_ROOT, 'docs');
